from fractions import Fraction

def rref(M, cols):
    R = [[Fraction(x) for x in row] for row in M]
    pivots = []
    for c in range(cols):
        r = len(pivots)
        p = r
        while p < len(R) and R[p][c] == 0:
            p = p + 1
        if p == len(R):
            continue
        R[r], R[p] = R[p], R[r]
        k = R[r][c]
        R[r] = [x / k for x in R[r]]
        for i in range(len(R)):
            k = R[i][c]
            if i != r and k != 0:
                R[i] = [R[i][j] - k * R[r][j] for j in range(len(R[i]))]
        pivots.append(c)
    return R, pivots

def vec(v):
    return "(" + ", ".join(str(x) for x in v) + ")"

def columns(vectors):
    return [[v[i] for v in vectors] for i in range(len(vectors[0]))]

def convert(way, basis, given):
    P = columns(basis)
    n = len(basis)
    if way == "to":
        R, pivots = rref([P[i] + [given[i]] for i in range(n)], n)
        print(f"  [x]_B = {vec([R[i][n] for i in range(n)])}")
    else:
        print(f"  x = {vec([sum(P[i][j] * given[j] for j in range(n)) for i in range(n)])}")

k = int(input())
for t in range(k):
    way, n = input().split()
    basis = [[Fraction(w) for w in input().split()] for j in range(int(n))]
    given = [Fraction(w) for w in input().split()]
    print(f"{way} the basis {', '.join(vec(b) for b in basis)}: {vec(given)}")
    convert(way, basis, given)

