from fractions import Fraction

def show(M):
    return "  ".join("[" + ", ".join(str(x) for x in row) + "]" for row in M)

def mul(A, B):
    return [[sum(A[i][k] * B[k][j] for k in range(len(B))) for j in range(len(B[0]))] for i in range(len(A))]

def inverse2(P):
    a, b = P[0]
    c, d = P[1]
    det = Fraction(a * d - b * c)
    return [[d / det, -b / det], [-c / det, a / det]]

def trace(M):
    return M[0][0] + M[1][1]

def det(M):
    return M[0][0] * M[1][1] - M[0][1] * M[1][0]

def in_basis(A, P):
    D = mul(inverse2(P), mul(A, P))
    print(f"  P^-1 A P = {show(D)}")
    print(f"  trace {trace(A)} -> {trace(D)}, det {det(A)} -> {det(D)}")
    if D[0][1] == 0 and D[1][0] == 0:
        print("  diagonal")
    else:
        print("  not diagonal")

k = int(input())
for t in range(k):
    A = [[Fraction(w) for w in input().split()] for i in range(2)]
    b1 = [Fraction(w) for w in input().split()]
    b2 = [Fraction(w) for w in input().split()]
    P = [[b1[0], b2[0]], [b1[1], b2[1]]]
    print(f"A = {show(A)}, P = {show(P)}")
    in_basis(A, P)
